//! Procedural surface tiles (`rmc_client::surfaces`): with the shipped
//! `assets/surfaces.ron` enabled, every material it lists draws with its
//! generated noise layers; a live edit from the Surfaces window regenerates
//! the edited tile and swaps the chunk material's tile array; turning the
//! noise off brings the image tiles back.
//!
//! Look and feel (CLAUDE.md rule 21): the test asserts what was set up (the
//! layers, the lookup, the bound array, the regenerated bytes) and that the
//! frames render and differ. The screenshots and the contact sheet of every
//! recipe are for the playtester.

use bevy::prelude::*;
use rmc_client::surfaces::{
    FACE_NAMES, SurfaceDesigner, SurfaceRequests, apply_requests, generate, layer_name,
};
use rmc_client::tiles::{LoadedTiles, TileSources};
use rmc_client::{ChunkEmissiveMaterial, ClientMaterials, EmissiveChunkMaterial, GameCamera};
use rmc_client::{MeshQueue, MeshStats};
use rmc_testkit::{TestApp, TestConfig, e2e};
use rmc_world::coords::CELL_SIZE_M;

#[test]
#[ignore]
fn surfaces_render() {
    let mut t = TestApp::new(TestConfig {
        tiles: true,
        size: (1280, 720),
        ..TestConfig::default()
    });
    e2e::run_scenario(&mut t, "surfaces_render", run);
}

fn settle(t: &mut TestApp) {
    for _ in 0..480 {
        t.step();
        let world = t.app().world();
        let stats = world.resource::<MeshStats>();
        if stats.initial_load_done
            && world.resource::<MeshQueue>().is_idle()
            && stats.awaiting_upload == 0
        {
            return;
        }
    }
    panic!("meshing did not settle");
}

fn set_camera(t: &mut TestApp, transform: Transform) {
    let world = t.app_mut().world_mut();
    let mut camera = world
        .query_filtered::<&mut Transform, With<GameCamera>>()
        .single_mut(world)
        .expect("one game camera");
    *camera = transform;
}

fn shoot(t: &mut TestApp, label: &str) -> image::RgbaImage {
    t.steps(4);
    let image = t.screenshot();
    let path = e2e::save_screenshot(&image, &format!("surfaces_render-{label}"), t.frame());
    eprintln!("screenshot: {}", path.display());
    assert_eq!(t.render_failure(), None, "{label} renders");
    image
}

fn material(t: &TestApp) -> ChunkEmissiveMaterial {
    let world = t.app().world();
    let handle = &world.resource::<EmissiveChunkMaterial>().0;
    world
        .resource::<Assets<ChunkEmissiveMaterial>>()
        .get(handle)
        .expect("the chunk material")
        .clone()
}

/// Every material `surfaces.ron` lists points each face at its noise layer.
fn assert_noise_faces(t: &TestApp) {
    let world = t.app().world();
    let set = &world.resource::<LoadedTiles>().0;
    let surfaces = &world.resource::<TileSources>().surfaces;
    let table = &world.resource::<ClientMaterials>().0;
    let lookup = material(t).extension.tile_lookup;
    assert!(surfaces.enabled);
    for key in surfaces.materials.keys() {
        let id = usize::from(table.id(key).expect("a known material").0);
        let slots = lookup.faces[id];
        for (f, slot) in [slots.x, slots.y, slots.z].into_iter().enumerate() {
            assert!(slot > 0, "{key} face {f} has a tile");
            let name = &set.layers[slot as usize - 1];
            assert!(name.starts_with(&format!("noise:{key}:")), "{key}: {name}");
        }
    }
}

/// Every recipe's tile repeated 2 × 2, so seams would show, in a grid.
fn contact_sheet(t: &TestApp) -> image::RgbaImage {
    let sources = t.app().world().resource::<TileSources>();
    let size = sources.config.size;
    let tiles: Vec<image::RgbaImage> = sources
        .surfaces
        .materials
        .values()
        .flat_map(|faces| (0..FACE_NAMES.len()).filter_map(move |i| faces.get(i)))
        .map(|recipe| generate(recipe, size))
        .collect();
    let cols = 6;
    let rows = tiles.len().div_ceil(cols) as u32;
    let cell = size * 2 + 8;
    let mut sheet = image::RgbaImage::from_pixel(
        cols as u32 * cell,
        rows * cell,
        image::Rgba([24, 24, 24, 255]),
    );
    for (i, tile) in tiles.iter().enumerate() {
        let (cx, cy) = ((i % cols) as u32 * cell + 4, (i / cols) as u32 * cell + 4);
        for (dx, dy) in [(0, 0), (size, 0), (0, size), (size, size)] {
            image::imageops::replace(&mut sheet, tile, (cx + dx).into(), (cy + dy).into());
        }
    }
    sheet
}

fn run(t: &mut TestApp) {
    settle(t);
    assert_noise_faces(t);
    let sheet = contact_sheet(t);
    let path = e2e::save_screenshot(&sheet, "surfaces_render-sheet", 0);
    eprintln!("contact sheet: {}", path.display());

    let bounds = t.host_world().bounds();
    let (min, max) = (bounds.min.0, bounds.max.0);
    let (x, z) = ((min.x + max.x) / 2, (min.z + max.z) / 2);
    let ground = i32::from(t.host_world().surface_y(x, z));
    let eye = Vec3::new(x as f32, (ground + 6) as f32, z as f32) * CELL_SIZE_M;
    set_camera(
        t,
        Transform::from_translation(eye).looking_to(Vec3::new(1.0, -0.25, 0.3), Vec3::Y),
    );
    let noise = shoot(t, "across");
    set_camera(
        t,
        Transform::from_translation(eye).looking_to(Vec3::new(0.2, -1.0, 0.1), Vec3::Y),
    );
    shoot(t, "down");

    // A live edit, as the Surfaces window makes it: the grass turns red.
    let before = material(t).extension.tiles.clone();
    let config = t.app().world().resource::<TileSources>().surfaces.clone();
    let key = "topsoil";
    let mut designer = SurfaceDesigner {
        open: true,
        config,
        selected: Some(key.into()),
        face: 1,
        status: String::new(),
    };
    let top = designer
        .config
        .materials
        .get_mut(key)
        .and_then(|f| f.top.as_mut())
        .expect("topsoil has a top recipe");
    top.colors = vec![(120, 20, 20), (170, 40, 30), (210, 70, 50)];
    let edited = top.clone();
    t.app_mut().world_mut().insert_resource(designer);
    apply_requests(
        t.app_mut().world_mut(),
        SurfaceRequests {
            edited: true,
            ..SurfaceRequests::default()
        },
    );
    let size = t.app().world().resource::<TileSources>().config.size as usize;
    let layer = t
        .app()
        .world()
        .resource::<LoadedTiles>()
        .0
        .layer(&layer_name(key, "top"))
        .expect("the edited layer")
        .to_vec();
    assert_eq!(
        &layer[..size * size * 4],
        generate(&edited, size as u32).as_raw(),
        "the edited tile is regenerated"
    );
    assert_ne!(
        material(t).extension.tiles,
        before,
        "the chunk material gets the new array"
    );
    let red = shoot(t, "edited");
    assert_ne!(red, noise, "the edit shows");

    // Noise off: the image tiles of tiles.ron come back.
    t.app_mut()
        .world_mut()
        .resource_mut::<SurfaceDesigner>()
        .config
        .enabled = false;
    apply_requests(
        t.app_mut().world_mut(),
        SurfaceRequests {
            rebuild: true,
            ..SurfaceRequests::default()
        },
    );
    let set = &t.app().world().resource::<LoadedTiles>().0;
    assert!(
        set.layers.iter().all(|l| !l.starts_with("noise:")),
        "{:?}",
        set.layers
    );
    assert!(!set.layers.is_empty(), "the image tiles load");
    set_camera(
        t,
        Transform::from_translation(eye).looking_to(Vec3::new(1.0, -0.25, 0.3), Vec3::Y),
    );
    shoot(t, "images");
}
